local _, addon = ...
addon.localeData.deDE.ambient = {
    DWARF = { "Bei meinen Ahnen, der Glaube trägt auch ohne Helm.", "Der Berg steht still. Das Licht in mir nicht.", "Wer die Tiefe kennt, erschrickt nicht vor Schatten.", "*klopft mit den Knöcheln gegen das heilige Symbol*", "*murmelt ein raues Gebet zwischen zusammengebissenen Zähnen*" },
    GNOME = { "Ich habe das Wunder nachgemessen. Es widerspricht jeder Gleichung.", "Ein bisschen Heilung, ein bisschen Feldforschung.", "Selbst die Dunkelheit hat messbare Grenzen. Vermutlich.", "*richtet seine Brille und prüft eine leuchtende Skizze*", "*notiert verwundert eine unerklärliche Beobachtung*" },
    HUMAN = { "Ein Eid ist nur so stark wie die Tat danach.", "Ich bete nicht für Ruhm, sondern für die Heimkehr.", "Wo Angst regiert, schulden wir einander Mut.", "*legt die Hand auf das Wappen am Herzen*", "*senkt kurz den Kopf und fasst neuen Mut*" },
    NIGHTELF = { "Unter Elunes Sternen ist selbst Schweigen ein Gebet.", "Der Mond schenkt Licht, ohne ein Wort zu verlangen.", "Auch ein langer Schatten wandert mit den Jahreszeiten.", "*zeichnet eine Mondsichel in die Luft*", "*lauscht dem Wind zwischen den Blättern*" },
    DRAENEI = { "Die Naaru lehrten Geduld. Sie erwähnten nicht, wie schwer sie ist.", "Ich habe Welten fallen sehen und dennoch Hoffnung bewahrt.", "Ein Schatten ist kein Ende. Er erinnert uns nur an die Richtung.", "*berührt behutsam einen Kristall am Gewand*", "*neigt ehrfürchtig das Haupt zu einem fernen Klang*" },
    ORC = { "Ehre ist nicht nur die Klinge, sondern auch die Hand, die sie senkt.", "Auch Krieger brauchen jemanden, der ihre Wunden sieht.", "Die Ahnen flüstern im Dunkeln und ich höre zu.", "*drückt die Faust an die Brust und grüßt die Ahnen*", "*steht schweigend und unbeugsam da*" },
    TROLL = { "Die Loa lachen selten über dieselben Dinge wie wir.", "Ich kenne einen Segen, aber der Loa verlangt eine Geschichte.", "Ein Schatten hat Zähne. Frag besser nicht, woher.", "*schüttelt einen kleinen Beutel mit Opfergaben*", "*zeichnet tanzend ein schiefes Zeichen in den Staub*" },
    TAUREN = { "Die Erdenmutter trägt auch jene, die ihren Weg verloren haben.", "Heilung wächst langsam, wie Gras nach dem Frost.", "Der Schatten einer Wolke ist kein Urteil über die Sonne.", "*berührt ehrfürchtig die Erde mit der Handfläche*", "*atmet tief ein und lauscht den fernen Ebenen*" },
    UNDEAD = { "Mein Glaube hat meinen Puls überlebt. Eine bemerkenswerte Leistung.", "Heilen ist schwierig, wenn man anatomisch widersprüchlich ist.", "Die Schatten sind alte Bekannte. Unangenehm gesprächig.", "*prüft ironisch, ob das eigene Herz noch schlägt*", "*richtet mit makabrem Ernst eine zerfaserte Stola*" },
    BLOODELF = { "Würde bedeutet, auch im Zweifel Haltung zu bewahren.", "Ein präziser Segen ist eine Kunstform.", "Schatten verraten gern, wer das Licht nur nachahmt.", "*glättet sorgfältig eine Falte des prächtigen Gewands*", "*betrachtet mit kühler Aufmerksamkeit eine arkane Reflexion*" },
    HIGH_ELF = { "Selbst im Exil findet das Licht einen Weg.", "Eine ruhige Hand heilt mehr als ein lauter Schwur.", "Erinnerungen werfen lange Schatten, auch nach Jahrhunderten.", "*hebt ein schlichtes Amulett mit feiner Gravur*", "*verweilt einen Atemzug lang bei einer alten Erinnerung*" },
    NEUTRAL = { "Manchmal ist Zuhören das erste Wunder.", "Ich bete nicht gegen die Angst, sondern für den Mut.", "Die Stille hat überraschend viele Stimmen.", "*faltet die Hände und schließt für einen Moment die Augen*", "*atmet bedächtig aus und lässt die Schultern sinken*" },
}
